import { describe, expect, it } from 'vitest';
import tool from './pdf-structure-inspector.tool';
import { meta } from './pdf-structure-inspector.meta';

type Result = {
  report?: { output: string; render?: string };
  notes?: string[];
  warnings?: string[];
  stats?: Record<string, string | number>;
};
type Table = { headers: string[]; rows: string[][] };

const table = (r: Result): Table => JSON.parse(r.report?.output ?? '') as Table;
const kv = (t: Table): Map<string, string> => new Map(t.rows.map((r) => [r[0] ?? '', r[1] ?? '']));

/**
 * Fixtures are generated by a small PDF writer and their verdicts come from
 * the foreign oracle `qpdf` (the implementation behind PDF repair), not from
 * this parser:
 *
 *   basic.pdf  (542 B)  qpdf --check exit 0, 2 pages, version 1.7,
 *                       not encrypted, not linearized;
 *                       xref: 1@15 2@64 3@127 4@215
 *   five.pdf   (884 B)  qpdf --check exit 0, 5 pages, version 1.4, 7 objects
 *   inc.pdf    (724 B)  qpdf --check exit 0, 2 pages, /Prev update appended,
 *                       xref adds 9@542
 *   enc.pdf   (1195 B)  qpdf --encrypt output; qpdf --check exit 2 ("invalid
 *                       password"), encrypted; no page count without the key
 *   broken.pdf (214 B)  truncated to half; qpdf --check exit 3,
 *                       "can't find startxref"
 */

function build(npages: number, version = '1.7', incremental = false): Uint8Array {
  const bodies = new Map<number, string>();
  const kids = Array.from({ length: npages }, (_, i) => `${3 + i} 0 R`).join(' ');
  bodies.set(1, '<< /Type /Catalog /Pages 2 0 R >>');
  bodies.set(2, `<< /Type /Pages /Kids [${kids}] /Count ${npages} >>`);
  for (let i = 0; i < npages; i += 1)
    bodies.set(3 + i, '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << >> >>');

  let out = `%PDF-${version}\n%âãÏÓ\n`;
  const offsets = new Map<number, number>();
  for (const num of [...bodies.keys()].sort((a, b) => a - b)) {
    offsets.set(num, out.length);
    out += `${num} 0 obj\n${bodies.get(num)}\nendobj\n`;
  }
  const xrefAt = out.length;
  const maxn = Math.max(...bodies.keys());
  out += `xref\n0 ${maxn + 1}\n0000000000 65535 f \n`;
  for (let num = 1; num <= maxn; num += 1)
    out += `${String(offsets.get(num)).padStart(10, '0')} 00000 n \n`;
  out += `trailer\n<< /Size ${maxn + 1} /Root 1 0 R /ID [<0123456789abcdef0123456789abcdef> <0123456789abcdef0123456789abcdef>] >>\n`;
  out += `startxref\n${xrefAt}\n%%EOF\n`;

  if (incremental) {
    const at = out.length;
    out +=
      '9 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << >> >>\nendobj\n';
    const x2 = out.length;
    out += `xref\n9 1\n${String(at).padStart(10, '0')} 00000 n \n`;
    out += `trailer\n<< /Size 10 /Root 1 0 R /Prev ${xrefAt} >>\n`;
    out += `startxref\n${x2}\n%%EOF\n`;
  }

  const bytes = new Uint8Array(out.length);
  for (let i = 0; i < out.length; i += 1) bytes[i] = out.charCodeAt(i) & 0xff;
  return bytes;
}

const BASIC = build(2);
const FIVE = build(5, '1.4');
const INC = build(2, '1.7', true);
const BROKEN = BASIC.slice(0, Math.floor(BASIC.length / 2));

const toFile = (data: Uint8Array, name = 'doc.pdf'): File =>
  new File([data.buffer as ArrayBuffer], name);

const run = async (data: Uint8Array, options: Record<string, string | number | boolean> = {}) =>
  (await tool.run({ files: [toFile(data)], options } as never)) as unknown as Result;

describe('pdf-structure-inspector meta contract', () => {
  it('registers with a unique id, on-device privacy and a short summary', () => {
    expect(meta.id).toBe('pdf-structure-inspector');
    expect(meta.category).toBe('pdf');
    expect(meta.privacy.processing).toBe('on-device');
    expect(meta.privacy.network).toBe('none');
    expect(meta.summary.length).toBeLessThanOrEqual(120);
  });

  it('exposes the four views and the object sample size', () => {
    const options = meta.options ?? [];
    expect(options.map((o) => o.key)).toEqual(['format', 'detail']);
    const format = options.find((o) => o.key === 'format');
    const choices = format?.type === 'select' ? format.choices.map((c) => c.value) : [];
    expect(choices).toEqual(['summary', 'objects', 'trailer', 'findings']);
  });
});

describe('summary matches the qpdf verdicts', () => {
  it('reports version, page count and object count for a clean two-page PDF', async () => {
    const m = kv(table(await run(BASIC)));
    expect(m.get('PDF version')).toBe('1.7');
    expect(m.get('Pages')).toBe('2');
    expect(m.get('Objects listed')).toBe('4');
    expect(m.get('Encrypted')).toBe('no');
    expect(m.get('Linearized')).toBe('no');
    expect(m.get('Offsets that miss')).toBe('0');
    expect(m.get('Findings')).toBe('0 error, 0 warning, 0 note');
  });

  it('reports the five-page 1.4 document from the oracle run', async () => {
    const m = kv(table(await run(FIVE)));
    expect(m.get('PDF version')).toBe('1.4');
    expect(m.get('Pages')).toBe('5');
    expect(m.get('Objects listed')).toBe('7');
    expect(m.get('Findings')).toBe('0 error, 0 warning, 0 note');
  });

  it('reports an appended incremental update', async () => {
    const m = kv(table(await run(INC)));
    expect(m.get('Incremental updates')).toBe('yes');
    expect(m.get('%%EOF markers')).toBe('2');
    expect(m.get('Objects listed')).toBe('5');
    expect(m.get('Offsets that miss')).toBe('0');
  });

  it('reports the file size it actually read', async () => {
    const m = kv(table(await run(BASIC)));
    expect(m.get('File size')).toBe('542 B');
  });
});

describe('cross-reference view', () => {
  it('lists objects in numeric order with the offsets qpdf prints', async () => {
    const t = table(await run(BASIC, { format: 'objects', detail: 50 }));
    expect(t.headers).toEqual(['Object', 'Gen', 'State', 'Offset', 'Lands']);
    expect(t.rows.map((r) => r[0])).toEqual(['1', '2', '3', '4']);
    expect(t.rows.map((r) => r[3])).toEqual(['15', '64', '127', '215']);
    expect(t.rows.every((r) => r[4] === 'ok')).toBe(true);
  });

  it('honours the detail cap', async () => {
    const t = table(await run(FIVE, { format: 'objects', detail: 2 }));
    expect(t.rows.length).toBe(2);
    expect(t.rows[0]?.[0]).toBe('1');
  });

  it('still reports the total object count when the sample is capped', async () => {
    const r = await run(FIVE, { format: 'objects', detail: 1 });
    expect(table(r).rows.length).toBe(1);
    expect(kv(table(await run(FIVE))).get('Objects listed')).toBe('7');
  });
});

describe('trailer view', () => {
  it('lists the trailer keys and the document root reference', async () => {
    const t = table(await run(BASIC, { format: 'trailer' }));
    const m = new Map(t.rows.map((r) => [r[0] ?? '', r[1] ?? '']));
    expect(m.get('Root')).toBe('1 0 R');
    expect(m.get('Size')).toBe('5');
    // /ID is an array of two hex strings; it is shown whole, not truncated.
    expect(m.get('ID')).toMatch(
      /^\[<0123456789abcdef0123456789abcdef> <0123456789abcdef0123456789abcdef>\]$/u,
    );
  });
});

describe('damage detection', () => {
  it('flags a truncated file as missing its startxref, like qpdf exit 3', async () => {
    const t = table(await run(BROKEN, { format: 'findings' }));
    const kinds = t.rows.map((r) => r[0]);
    expect(kinds).toContain('missing-startxref');
    expect(kinds).toContain('no-eof');
    expect(t.rows.some((r) => r[1] === 'ERROR')).toBe(true);
  });

  it('reports structural errors in the summary for a truncated file', async () => {
    const m = kv(table(await run(BROKEN)));
    const findings = m.get('Findings') ?? '';
    expect(findings).toMatch(/^[1-9]\d* error/u);
  });

  it('rejects a file with no PDF header', async () => {
    const notPdf = new Uint8Array([0x50, 0x4b, 0x03, 0x04, 0x00]);
    await expect(run(notPdf)).rejects.toThrow(/does not look like a PDF/u);
  });

  it('rejects an empty file', async () => {
    await expect(run(new Uint8Array(0))).rejects.toThrow(/empty/u);
  });
});

describe('encryption and linearization', () => {
  it('reports a linearized document', async () => {
    const linear = new TextEncoder().encode(
      '%PDF-1.7\n' +
        '1 0 obj\n<< /Linearized 1 /L 1000 /H [100 200] /O 3 /E 500 /N 1 /T 900 >>\nendobj\n' +
        'startxref\n0\n%%EOF\n',
    );
    const m = kv(table(await run(linear)));
    expect(m.get('Linearized')).toBe('yes');
  });

  it('reports an encrypted document from its trailer /Encrypt entry', async () => {
    const text =
      '%PDF-1.7\n' +
      '1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n' +
      '3 0 obj\n<< /Filter /Standard /V 1 /R 2 /O <00> /U <00> /P -4 >>\nendobj\n' +
      'xref\n0 4\n0000000000 65535 f \n0000000009 00000 n \n0000000000 00000 f \n0000000048 00000 n \n' +
      'trailer\n<< /Size 4 /Root 1 0 R /Encrypt 3 0 R >>\nstartxref\n110\n%%EOF\n';
    const bytes = new Uint8Array(text.length);
    for (let i = 0; i < text.length; i += 1) bytes[i] = text.charCodeAt(i) & 0xff;
    const m = kv(table(await run(bytes)));
    expect(m.get('Encrypted')).toBe('yes');
    const findings = table(await run(bytes, { format: 'findings' }));
    expect(findings.rows.some((r) => r[0] === 'encrypted')).toBe(true);
  });
});

describe('input guards', () => {
  it('rejects a missing file', async () => {
    await expect(tool.run({ files: [], options: {} } as never)).rejects.toThrow(/No PDF/u);
  });

  it('falls back to the summary for an unknown view', async () => {
    const r = await run(BASIC, { format: 'nope' });
    expect(kv(table(r)).get('PDF version')).toBe('1.7');
    expect(r.warnings?.some((w) => w.includes('nope'))).toBe(true);
  });

  it('clamps a negative detail value to zero rows', async () => {
    const t = table(await run(BASIC, { format: 'objects', detail: -5 }));
    expect(t.rows.length).toBe(0);
  });
});
